entries[28282] = { ["name"] = "Formel: Schild - Erhebliche Ausdauer", ["text"] = "Benötigt Verzauberkunst (325)\nBenutzen: Lehrt Euch18 Schilde dauerhaft zu verzaubern18 sodass die Ausdauer um 18 erhöht wird. Erfordert einen Gegenstand der Stufe 18 oder höher.\nEinen Schild dauerhaft verzaubern, sodass die Ausdauer um 18 erhöht wird.\nVerkaufspreis:" }
